    {"id":13,"name":"Equilibrium reconstruction (Grad–Shafranov / EFIT-like)","module":"equilibrium_reconstruction","function":"reconstruct_equilibrium","execution_contract":{"schema_version":"1.0","execution_level":"analysis_pipeline","completeness":"complete_with_declared_scope","input_specs":[{"name":"R_m","unit":"m","description":"Strictly increasing uniform major-radius grid, positive values.","required":True},{"name":"Z_m","unit":"m","description":"Strictly increasing uniform vertical grid.","required":True},{"name":"boundary_flux_Wb_rad","unit":"Wb/rad","description":"Finite 2-D prescribed poloidal-flux boundary grid with shape (len(Z_m), len(R_m)); perimeter values are fixed.","required":True},{"name":"psi_profile","unit":"normalized flux","description":"Strictly increasing profile coordinate within [0,1], at least two points.","required":True},{"name":"pressure_gradient_Pa_per_Wb","unit":"Pa/Wb","description":"Pressure derivative profile dp/dψ evaluated against normalized flux coordinate.","required":True},{"name":"ffprime_T2","unit":"T²","description":"F dF/dψ profile evaluated against normalized flux coordinate.","required":True},{"name":"max_iterations","unit":"count","description":"Positive integer iteration cap.","required":False},{"name":"tolerance","unit":"relative","description":"Positive finite convergence tolerance; convergence also requires equation-residual acceptance.","required":False},{"name":"relaxation","unit":"dimensionless","description":"SOR relaxation factor in (0,2).","required":False}],"output_specs":[{"name":"psi_Wb_rad","unit":"Wb/rad","description":"Reconstructed flux grid with prescribed perimeter fixed."},{"name":"B_R_T","unit":"T","description":"Radial magnetic-field component derived from flux gradients."},{"name":"B_Z_T","unit":"T","description":"Vertical magnetic-field component derived from flux gradients."},{"name":"B_poloidal_T","unit":"T","description":"Magnitude of poloidal magnetic field."},{"name":"psi_normalized","unit":"dimensionless","description":"Min-max normalized flux grid."},{"name":"converged","unit":"boolean","description":"True only when iterative update and interior Grad–Shafranov equation residual satisfy acceptance criteria."},{"name":"equation_residual_relative_rms","unit":"dimensionless","description":"Interior normalized PDE residual."},{"name":"iterations","unit":"count","description":"Number of solver iterations."},{"name":"equation_residual_rms_Wb_rad_m-2","unit":"Wb rad^-1 m^-2","description":"Interior equation residual RMS."},{"name":"equation_residual_max_abs_Wb_rad_m-2","unit":"Wb rad^-1 m^-2","description":"Maximum absolute interior equation residual."}],"assumptions":["Axisymmetric Grad–Shafranov operator on a uniform R-Z grid.","Pressure-gradient and F F-prime profiles are interpolated against min-max normalized flux of the current iterate.","The prescribed perimeter flux is supplied by the user and is held fixed."],"preprocessing":["Validate finite uniform grids, positive R, boundary shape, profile dimensions, monotonic normalized-flux coordinate, and solver controls."],"algorithm":"Successive over-relaxation finite-difference solution of Δ*ψ = -μ0 R² p\u0027(ψ) - F F\u0027(ψ), with fixed prescribed boundary; derive magnetic field components and report equation residuals.","uncertainty_model":"not_provided; no uncertainty propagation is performed by the solver.","limitations":["The prescribed-boundary solver requires boundary flux and p'(ψ)/F F'(ψ) profiles in consistent units.","The public-reference workflow estimates F F'(ψ) from an existing EFIT flux map with p'(ψ)=0; its reference comparison is in-sample and must not be interpreted as independent validation.","Automatic free-boundary inference from coil currents and machine-specific magnetic sensor Green functions is not included in the public-reference profile-estimation path."],"function_links":["tokamak_analysis.equilibrium_reconstruction.reconstruct_equilibrium","tokamak_analysis.equilibrium_reconstruction.grad_shafranov_physical_relation","tokamak_analysis.equilibrium_reconstruction.reconstruct_equilibrium_inverse","tokamak_analysis.equilibrium_reconstruction.infer_grad_shafranov_profiles_from_flux","tokamak_analysis.equilibrium_reconstruction.reconstruct_equilibrium_from_reference_flux"],"raw_data_to_physics":True}},
    {"id":14,"name":"Polarimetry / Faraday rotation","module":"polarimetry","function":"analyze_polarimetry","execution_contract":{"schema_version":"1.0","execution_level":"analysis_pipeline","completeness":"complete_with_declared_scope","input_specs":[{"name":"wavelength_m","unit":"m","required":True,"description":"Calibrated positive finite vacuum wavelength; use one-dimensional arrays."},{"name":"rotation_rad","unit":"rad","required":True,"description":"Signed calibrated Faraday rotation angle matching wavelength_m."},{"name":"rotation_uncertainty_rad","unit":"rad","required":False,"minimum":0,"description":"Optional 1-sigma uncertainty, scalar or elementwise."},{"name":"wavelength_uncertainty_m","unit":"m","required":False,"minimum":0,"description":"Optional 1-sigma wavelength uncertainty, scalar or elementwise."},{"name":"electron_density_m3","unit":"m^-3","required":False,"minimum":1e-15,"description":"Optional positive density; required with path_length_m to estimate average field."},{"name":"path_length_m","unit":"m","required":False,"minimum":1e-15,"description":"Optional positive chord length; required with electron_density_m3."},{"name":"density_uncertainty_m3","unit":"m^-3","required":False,"minimum":0,"description":"Optional 1-sigma density uncertainty."},{"name":"path_length_uncertainty_m","unit":"m","required":False,"minimum":0,"description":"Optional 1-sigma path-length uncertainty."}],"output_specs":[{"name":"line_integrated_ne_B_parallel_m-2_T","unit":"m^-2 T","description":"Signed line integral of electron density times parallel field."},{"name":"line_integrated_ne_B_parallel_uncertainty_m-2_T","unit":"m^-2 T","description":"First-order uncertainty from rotation and wavelength."},{"name":"average_B_parallel_T","unit":"T","description":"Chord-averaged parallel field when density and path length are supplied."},{"name":"average_B_parallel_uncertainty_T","unit":"T","description":"Optional first-order uncertainty including supplied density and path-length errors."}],"assumptions":["Cold-plasma Faraday relation in SI units; calibrated wavelength and rotation are supplied.","Signed rotation follows the instrument handedness and viewing-coordinate convention.","Average field assumes uniform supplied density along a single chord; this is not a spatial inversion."],"preprocessing":["Require matching non-empty 1-D arrays, finite positive wavelength and finite signed rotation.","Validate uncertainties as finite and non-negative; require density and path length together and positive."],"algorithm":"Apply rotation = C_F * wavelength^2 * integral(n_e B_parallel dl), C_F=e^3/(8*pi^2*epsilon_0*m_e^2*c^3). Optionally divide the line integral by supplied density and chord length for a chord-averaged parallel field.","uncertainty_model":"First-order independent-error propagation for rotation and wavelength; optional average-field propagation includes density and path-length uncertainties. Calibration and model discrepancy are excluded.","limitations":["Requires calibrated rotation and wavelength; raw polarimeter electronics calibration is out of scope.","A single chord yields a line integral, not a spatially resolved field or equilibrium reconstruction.","Average field assumes uniform supplied density and known chord length.","Refraction, additional birefringence, instrumental offsets and sign conventions require experiment-specific treatment."],"function_links":["tokamak_analysis.polarimetry.analyze_polarimetry"],"raw_data_to_physics":True}},
    {"id":15,"name":"Magnetic flux / poloidal flux","module":"poloidal_flux","function":"reconstruct_poloidal_flux","execution_contract":{"schema_version":"1.0","execution_level":"analysis_pipeline","completeness":"complete_with_declared_scope","input_specs":[{"name":"R_m","unit":"m","description":"Strictly increasing major-radius grid, positive and unique.","required":True},{"name":"Z_m","unit":"m","description":"Strictly increasing vertical grid, unique.","required":True},{"name":"B_R_T","unit":"T","description":"Calibrated radial magnetic-field grid with shape (len(Z_m),len(R_m)).","required":True},{"name":"B_Z_T","unit":"T","description":"Calibrated vertical magnetic-field grid with shape (len(Z_m),len(R_m)).","required":True},{"name":"initial_flux_Wb","unit":"Wb","description":"Optional flux gauge at reference grid point; finite scalar.","required":False},{"name":"reference_index","unit":"index pair","description":"Optional (Z index, R index) where initial_flux_Wb is imposed.","required":False}],"output_specs":[{"name":"poloidal_flux_Wb","unit":"Wb","description":"Path-integrated axisymmetric poloidal flux map with reference gauge applied."},{"name":"poloidal_flux_change_Wb","unit":"Wb","description":"Flux map relative to the supplied initial flux."},{"name":"dpsi_dR_Wb_m","unit":"Wb m^-1","description":"Numerical radial derivative of reconstructed flux."},{"name":"dpsi_dZ_Wb_m","unit":"Wb m^-1","description":"Numerical vertical derivative of reconstructed flux."},{"name":"consistency_residual_R_Wb_m","unit":"Wb m^-1","description":"Residual of dpsi/dR = R B_Z."},{"name":"consistency_residual_Z_Wb_m","unit":"Wb m^-1","description":"Residual of dpsi/dZ = -R B_R."},{"name":"diagnostics","unit":"structured","description":"Grid shape, flux range, and derivative consistency residuals."}],"assumptions":["Axisymmetric cylindrical coordinates (R,Z).","Input B_R and B_Z are calibrated in tesla on a rectangular grid.","The initial/reference flux fixes the additive gauge; absolute flux requires an independent reference condition."],"preprocessing":["Validate finite values, positive/increasing R, increasing Z, matching grid shapes, and reference index."],"algorithm":"Integrate dpsi/dR = R B_Z along R and dpsi/dZ = -R B_R along Z using trapezoidal integration; report derivative consistency residuals.","uncertainty_model":"No uncertainty propagation is inferred because measurement uncertainties and covariance are not inputs; derivative residuals are diagnostics, not uncertainty estimates.","limitations":["Not an EFIT or Grad-Shafranov equilibrium solver.","No plasma current, pressure profile, or separatrix reconstruction is inferred.","No instrument calibration is performed; magnetic fields must be calibrated upstream.","Path integration can be path-dependent for noisy or non-integrable fields; inspect residuals."],"function_links":["tokamak_analysis.poloidal_flux.reconstruct_poloidal_flux"],"raw_data_to_physics":True,"workflow_modes":[{"name":"calibrated_B_R_B_Z_grid","function":"poloidal_flux.reconstruct_poloidal_flux","inputs":["R_m (m)","Z_m (m)","B_R_T (T grid)","B_Z_T (T grid)","initial_flux_Wb (optional)","reference_index (optional)"],"outputs":["poloidal_flux_Wb","poloidal_flux_change_Wb","derivative consistency residuals","diagnostics"],"scope":"Reconstructs a relative poloidal-flux map from calibrated axisymmetric magnetic-field grids; not equilibrium reconstruction."}] }},
