    {"id":30,"name":"Collective Thomson / coherent scattering (CTS)","module":"cts_analysis","function":"analyze_cts_spectrum","execution_contract":{"schema_version":"2.0","execution_level":"analysis_pipeline","completeness":"complete_with_declared_scope","input_specs":[{"name": "frequency_shift_Hz", "unit": "Hz", "required": True}, {"name": "spectrum", "unit": "calibrated spectral power", "required": True}, {"name": "probe_frequency_Hz", "unit": "Hz", "required": True}, {"name": "scattering_geometry", "unit": "structured", "required": True}, {"name": "ion_species", "unit": "species metadata", "required": True}, {"name": "ion_fractions", "unit": "charge-density fraction", "required": True}, {"name": "instrument_response", "unit": "normalized frequency response matrix", "required": True}, {"name": "signal_uncertainty", "unit": "same as spectrum, 1-sigma", "required": False}, {"name": "fast_ion", "unit": "structured", "required": False}, {"name": "parameter_bounds", "unit": "structured", "required": False}, {"name": "spectral_covariance", "unit": "frequency-bin covariance matrix", "required": False}, {"name": "instrument_response_uncertainty", "unit": "frequency-response matrix 1-sigma", "required": False}, {"name": "external_parameter_uncertainties", "unit": "structured 1-sigma mapping", "required": False}, {"name": "inversion_method", "unit": "text", "required": False, "description": "differential_evolution, improved_genetic or regularized."}, {"name": "regularization_strength", "unit": "dimensionless", "required": False}, {"name": "electron_velocity_projection_m_s", "unit": "m s^-1", "required": True, "description": "Explicit externally supplied electron-flow projection. Supply 0 only when stationary electron flow is intentionally assumed."}, {"name": "electron_density_initial_m3", "unit": "m^-3; optimizer initial estimate", "required": False}, {"name": "electron_temperature_initial_eV", "unit": "eV; optimizer initial estimate", "required": False}, {"name": "ion_temperature_initial_eV", "unit": "eV; common ion-temperature optimizer initial estimate", "required": False}, {"name": "ion_velocity_initial_m_s", "unit": "m s^-1; common projected ion-flow optimizer initial estimate", "required": False}, {"name": "global_search", "unit": "boolean; enables differential-evolution global initialization", "required": False}, {"name": "random_seed", "unit": "integer; deterministic search seed", "required": False}, {"name": "response_mc_samples", "unit": "count", "required": False}],"output_specs":[{"name": "electron_density_m3", "unit": "m^-3"}, {"name": "electron_temperature_eV", "unit": "eV"}, {"name": "ion_temperature_eV", "unit": "eV"}, {"name": "ion_velocity_projection_m_s", "unit": "m s^-1"}, {"name": "fit_covariance", "unit": "parameter covariance"}, {"name": "fitted_spectrum", "unit": "same as spectrum"}, {"name": "residual", "unit": "same as spectrum"}, {"name": "fast_ion_vdf_probability_density_m_s_inverse", "unit": "s m^-1"}, {"name": "fast_ion_vdf_uncertainty_m_s_inverse", "unit": "s m^-1"}, {"name": "fast_ion_vdf_covariance", "unit": "(s m^-1)^2"}, {"name": "model_discrepancy_covariance", "unit": "mixed physical parameter covariance"}, {"name": "response_parameter_covariance", "unit": "mixed physical parameter covariance"}, {"name": "electron_velocity_projection_m_s", "unit": "m s^-1", "description": "Explicit externally supplied electron-flow projection used in the CTS forward model; not fitted."}, {"name": "electron_velocity_projection_is_fitted", "unit": "boolean", "description": "Always false; electron-flow projection is an external fixed input."}, {"name": "electron_velocity_projection_input_uncertainty_m_s", "unit": "m s^-1; optional 1-sigma", "description": "User-supplied uncertainty for the external electron-flow projection."}],"assumptions":["Unmagnetized electrostatic longitudinal dielectric response.","Maxwellian bulk species and fixed supplied ion composition.","Electron-flow projection is supplied explicitly; zero is not assumed silently.","One common ion temperature and projected ion flow are shared by all background species.","Optional hot-ion component is a two-Maxwellian approximation."],"preprocessing":["Validate calibrated frequency-shift spectrum, probe frequency, geometry, species composition and normalized response matrix."],"algorithm":"Frequency-domain multi-species dielectric forward model with differential-evolution or genetic global initialization and bounded least-squares refinement.","uncertainty_model":"Local Jacobian covariance with optional full spectral covariance whitening; supplied response-matrix and external-parameter uncertainties are propagated by Monte Carlo. Model discrepancy is retained as a separate covariance component.","limitations":["Not a full magnetized electromagnetic CTS model or ray-tracing solver.","Absolute power transfer and polarization coupling are not inverted.","One common Ti and projected ion flow are used across background species; species-specific ion parameters are not inferred.","Fast-ion VDF support is one-dimensional; it is not a full 3-D distribution reconstruction."],"function_links":["tokamak_analysis.cts_analysis.analyze_cts_spectrum","tokamak_analysis.cts_analysis.cts_spectral_density"],"raw_data_to_physics":False,"calibrated_measurements_to_physics":True}},
