    {"id":46,"name":"Thomson spatial profile reconstruction","module":"thomson_workflow","function":"reconstruct_thomson_profile_from_spectra","execution_contract":{
        "schema_version": "1.0",
        "execution_level": "analysis_pipeline",
        "completeness": "complete_with_declared_scope",
        "input_specs":             [{"name": "wavelength_nm", "unit": "nm; 1-D shared or channel x wavelength 2-D", "required": True}, {"name": "spectra", "unit": "calibrated spectral intensity; channel x wavelength", "required": True}, {"name": "radius_m", "unit": "m; one per channel", "required": True}, {"name": "laser_wavelength_nm", "unit": "nm", "required": True}, {"name": "scattering_angle_rad", "unit": "rad", "required": True}, {"name": "instrument_response", "unit": "measured normalized response matrix/kernel/callable", "required": True}, {"name": "signal_uncertainty", "unit": "spectral intensity; pointwise 1-sigma", "required": False}, {"name": "joint_spectral_covariance", "unit": "full channel-major spectral covariance; mutually exclusive with signal_uncertainty", "required": False, "description": "Full positive-definite covariance in channel-major order; cannot be combined with signal_uncertainty."}, {"name": "model", "unit": "non_collective_maxwellian, non_collective_kappa or collective_maxwellian", "required": False}, {"name": "laser_wavelength_uncertainty_nm", "unit": "nm; 1-sigma", "required": False}, {"name": "scattering_angle_uncertainty_rad", "unit": "rad; 1-sigma; collective scalar geometry MC or non-collective analytic propagation", "required": False}, {"name": "incident_direction_uncertainty", "unit": "dimensionless component-wise 1-sigma 3-vector; collective only", "required": False}, {"name": "scattered_direction_uncertainty", "unit": "dimensionless component-wise 1-sigma 3-vector; collective only", "required": False}, {"name": "instrument_response_uncertainty", "unit": "response-matrix 1-sigma", "required": False}, {"name": "instrument_response_mc_samples", "unit": "count", "required": False}, {"name": "instrument_response_mc_min_success_fraction", "unit": "dimensionless", "required": False}, {"name": "laser_power_w", "unit": "W; incident power at scattering volume", "required": False}, {"name": "interaction_length_m", "unit": "m", "required": False}, {"name": "collection_solid_angle_sr", "unit": "sr", "required": False}, {"name": "optical_efficiency", "unit": "dimensionless", "required": False}, {"name": "incident_polarization", "unit": "dimensionless 3-vector", "required": False}, {"name": "incident_direction", "unit": "dimensionless 3-vector", "required": False}, {"name": "scattered_direction", "unit": "dimensionless 3-vector", "required": False}, {"name": "spectral_power_density_calibrated", "unit": "boolean; must be true to identify absolute density from W/nm spectra", "required": False, "description": "Explicit declaration that measured spectral density is calibrated in W/nm; false by default."}, {"name": "laser_power_uncertainty_W", "unit": "W; 1-sigma", "required": False}, {"name": "interaction_length_uncertainty_m", "unit": "m; 1-sigma", "required": False}, {"name": "collection_solid_angle_uncertainty_sr", "unit": "sr; 1-sigma", "required": False}, {"name": "optical_efficiency_uncertainty", "unit": "dimensionless; 1-sigma", "required": False}, {"name": "polarization_factor_uncertainty", "unit": "dimensionless; 1-sigma", "required": False}, {"name": "density_relative_covariance", "unit": "6x6 relative covariance", "required": False, "description": "Per-channel (shared 6x6 or channel-specific N x 6 x 6) covariance for scattered power and five optical inputs. It does not imply cross-channel correlations; use joint_density_relative_covariance for those. Mutually exclusive with scalar optical uncertainties and joint_spectral_covariance."}, {"name": "ion_species", "unit": "explicit collective ion species list", "required": False}, {"name": "ion_fractions", "unit": "one charge-density fraction per ion species; sum to one", "required": False}, {"name": "ion_temperature_eV", "unit": "eV; one fixed external value per ion species", "required": False}, {"name": "ion_velocity_m_s", "unit": "m s^-1; species x 3 fixed external flow vectors", "required": False}, {"name": "electron_velocity_m_s", "unit": "m s^-1; fixed external 3-vector", "required": False}, {"name": "ion_temperature_uncertainty_eV", "unit": "eV; per species 1-sigma", "required": False}, {"name": "ion_velocity_uncertainty_m_s", "unit": "m s^-1; species x 3 component-wise 1-sigma", "required": False}, {"name": "electron_velocity_uncertainty_m_s", "unit": "m s^-1; 3-vector component-wise 1-sigma", "required": False}, {"name": "collective_initial_density_m3", "unit": "m^-3; optimizer initial estimate, not fixed inferred value", "required": False, "description": "Numerical optimizer seed only; not a fixed physical input."}, {"name": "collective_initial_temperature_eV", "unit": "eV; optimizer initial estimate, not fixed inferred value", "required": False, "description": "Numerical optimizer seed only; not a fixed physical input."}, {"name": "collective_density_bounds_m3", "unit": "m^-3; optional positive optimizer bounds", "required": False}, {"name": "collective_temperature_bounds_eV", "unit": "eV; optional positive optimizer bounds", "required": False}, {"name": "collective_external_parameter_mc_samples", "unit": "count", "required": False}, {"name": "joint_density_relative_covariance", "unit": "(6*n_channels) x (6*n_channels) relative covariance", "required": False, "description": "Non-collective models only. Complete channel-major covariance for six density-inversion inputs per channel, including cross-channel correlations. Mutually exclusive with density_relative_covariance, joint_spectral_covariance, instrument_response_uncertainty and scalar optical-factor uncertainties. Collective mode exposes its external-parameter covariance separately."}],
        "output_specs":             [{"name": "electron_temperature_profile_eV", "unit": "eV"}, {"name": "electron_density_profile_m3", "unit": "m^-3", "description": "Only where identifiable from selected model and supplied calibration/geometry."}, {"name": "electron_velocity_projection_profile_m_s", "unit": "m s^-1"}, {"name": "channels", "unit": "structured", "description": "Per-channel fit, residuals, covariance, assumptions and provenance."}, {"name": "electron_temperature_uncertainty_profile_eV", "unit": "eV"}, {"name": "electron_density_uncertainty_profile_m3", "unit": "m^-3"}, {"name": "electron_velocity_projection_uncertainty_profile_m_s", "unit": "m s^-1", "description": "Per-channel uncertainty of the fitted non-collective projection; in collective mode available when supplied flow-vector and/or beam-geometry uncertainties are propagated by Monte Carlo."}, {"name": "joint_inference", "unit": "structured", "description": "Joint GLS parameters, covariance and fit diagnostics when joint_spectral_covariance is supplied."}, {"name": "collective_external_parameter_covariance", "unit": "parameter covariance", "description": "Cross-channel covariance of density, temperature and projected electron/ion flows from collective external-input Monte Carlo."}, {"name": "collective_external_parameter_covariance_order", "unit": "ordered labels", "description": "Names corresponding to the collective external-parameter covariance rows and columns."}, {"name": "model_discrepancy_covariance", "unit": "parameter covariance", "description": "Residual-based model-adequacy covariance, only when a supported reduced chi-square and fit covariance are available."}, {"name": "electron_density_joint_covariance_m6", "unit": "n_channels x n_channels; m^-6", "description": "Full cross-channel absolute-density covariance propagated from joint_density_relative_covariance."}, {"name": "electron_density_cross_channel_covariance_available", "unit": "boolean"}, {"name": "electron_density_external_parameter_covariance_m6", "unit": "n_channels x n_channels; m^-6", "description": "Collective external-parameter Monte Carlo contribution to cross-channel absolute-density covariance; distinct from per-channel spectral-fit uncertainty."}],
        "assumptions":             [
                "Input spectra and wavelength axes are measured and calibrated; this analysis does not calibrate the diagnostic.",
                "Spatial coordinates are supplied for each measured spectral channel.",
                "Non-collective Maxwellian inference assumes an isotropic, non-relativistic Maxwellian electron population.",
                "Collective Maxwellian inference requires explicitly supplied ion species, ion temperatures and ion/electron flow vectors; these remain fixed external inputs and are not inferred from the Thomson spectrum.",
                "Absolute non-collective density requires spectral intensity in W/nm and the complete optical-power, geometry and polarization factors."
            ],
        "preprocessing":             [
                "Validate finite channel-by-wavelength arrays, strictly increasing wavelength axes, channel-to-radius correspondence and response-matrix normalization.",
                "Apply the supplied instrument response in the forward model; do not replace it with a Gaussian width unless the user supplies such a response."
            ],
         "algorithm": "Fit measured multi-channel Thomson spectra with a forward model convolved by the supplied instrument response; infer per-channel electron temperature and supported flow projection, and infer absolute density only when calibrated power and complete optical geometry are supplied.",
         "uncertainty_model": "Non-collective fit covariance is combined with supplied LSF uncertainty; full channel-major covariance is handled by joint GLS for Maxwellian/Kappa and final absolute density is recomputed from the joint integrated area. Collective Monte Carlo propagates supplied ion-temperature, ion/electron flow-vector, laser-wavelength, scattering-angle or beam-direction component, and response-matrix uncertainties; its covariance includes density, temperature and projected flows. A supplied 6x6 density_relative_covariance is authoritative and mutually exclusive with scalar optical uncertainties. Excess reduced chi-square is exposed separately as a model-adequacy covariance diagnostic, not experimental validation.",
        "limitations":             [
                "Full 3-D relativistic photon-geometry integration and arbitrary non-Maxwellian VDF inversion are not implemented; a projected Maxwell-Juttner approximation and parameterized kappa model are available for non-collective spectra.",
                "Collective inference uses the optional PlasmaPy Maxwellian dielectric model and requires explicit ion species and ion temperatures.",
                "Absolute density is not identifiable from spectral shape alone; it requires absolute W/nm intensity and all stated optical geometry and polarization factors.",
                "Non-collective LSF uncertainty is propagated by Monte Carlo when supplied; full cross-wavelength and cross-channel covariance is supported for Maxwellian/Kappa joint GLS.",
                "Collective beam-direction component uncertainty is propagated as independent component-wise Gaussian perturbations; correlations among vector components and with other external parameters are not modeled.",
                "A 6x6 density_relative_covariance is the sole optical-density uncertainty model; its scattered-power marginal must represent the complete area uncertainty.",
                "No independent experimental validation is claimed."
            ],
        "function_links": ["tokamak_analysis.thomson_workflow.reconstruct_thomson_profile_from_spectra"],
        "raw_data_to_physics": False,
        "calibrated_measurements_to_physics": True,
        "note": "This registered profile subanalysis consumes measured, calibrated multi-channel Thomson spectra and delegates to the canonical physical forward-inference engine. It does not accept pre-derived ne/Te profile points. No detector calibration or independent experimental validation is performed.",
        "workflow_modes": [{"name":"spatial_profile_from_measured_spectra","function":"tokamak_analysis.thomson_workflow.reconstruct_thomson_profile_from_spectra","inputs":["wavelength_nm","spectra (channel × wavelength)","radius_m","laser_wavelength_nm","scattering_angle_rad","instrument_response","optional spectral, response and external-parameter uncertainties/covariances","optional collective ion composition/temperature/flow inputs","optional absolute-density optical geometry"],"outputs":["electron_temperature_profile_eV","electron_density_profile_m3 where identifiable","electron_velocity_projection_profile_m_s","channel-resolved fits, uncertainties and joint covariance where supported"],"scope":"Profile-oriented output from the canonical physical inference of measured calibrated multi-channel spectra; no pre-derived ne/Te profile input."}],"completion_scope": "Profile-oriented output from the canonical measured-spectrum Thomson physical inference, with the same models and uncertainty scope as Analysis 1. No interpolation or smoothing of pre-derived ne/Te profile points is performed. Full 3-D relativistic and collective non-Maxwellian models remain outside the implemented scope; no independent experimental validation."
    }},
